from pathlib import Path
import json,html
r=Path('reports/current-final-review-2026-10-11');metadata=json.load(open(r/'raw/capture-metadata.json'));by={c['file']:c for c in metadata['captures']};cards=[]
for p in sorted((r/'screenshots').rglob('*.png')):
 f=p.relative_to(r).as_posix();c=by.get(f,{});cam=c.get('camera');st=c.get('stats',{});vp=c.get('viewport',{});note=c.get('note','Supplemental actual browser evidence; see raw test/capture JSON. No camera pose measurement available for separate-page/fallback captures.');group='mobile' if '/mobile/' in f else 'desktop'
 details='Camera '+json.dumps(cam,separators=(',',':')) if cam else 'Camera: unmeasured / not applicable (fallback)'
 if cam:details+=f" | {vp.get('width')}×{vp.get('height')} requestedDPR{vp.get('requestedDpr')} effectiveDPR{st.get('dpr')} tier{c.get('snapshot',{}).get('quality')}"
 cards.append(f'<figure data-group="{group}"><a href="{html.escape(f)}"><img loading="lazy" src="{html.escape(f)}" alt="{html.escape(p.stem)}"></a><figcaption><strong>{html.escape(f)}</strong><p>{html.escape(note)}</p><code>{html.escape(details)}</code><p><a href="{html.escape(f)}" download>Original PNG</a></p></figcaption></figure>')
references=[]
for p in sorted((r/'references').glob('*')):
 if p.suffix.lower() not in ['.png','.jpeg','.jpg']:continue
 f=p.relative_to(r).as_posix();references.append(f'<figure><a href="{f}"><img loading="lazy" src="{f}" alt="{html.escape(p.name)}"></a><figcaption>Historical/reference — {html.escape(p.name)}. Inspiration or older capture, not current implementation.</figcaption></figure>')
comparisons=[]
for profile in ['desktop','mobile']:
 for mode in ['baseline','acceptance']:
  f=f'historical/tunnel-exit-comparison/{mode}-{profile}-stage-looking-back.png';comparisons.append(f'<figure><a href="{f}"><img loading="lazy" src="{f}"></a><figcaption>Prior matched {profile} tunnel correction: {mode}. These images were created before this review; metadata retained under historical/tunnel-exit-comparison.</figcaption></figure>')
recordings=[]
for p in (r/'recordings').glob('*.webm'):
 f=p.relative_to(r).as_posix();recordings.append(f'<video controls preload="metadata" src="{f}"></video><p><a href="{f}">Original actual browser recording</a>. Begins with public landing → tunnel → hub → forward walk → stage → movie → Esc → boundary → return → map. Later sections use explicitly seeded perimeter fixtures. Tracing/recording slows software rendering; not a performance benchmark. See visitor.json for recorded route failure.</p>')
page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Gullyverse current final review — evidence</title><style>body{margin:0;background:#101513;color:#ecede7;font:15px/1.5 system-ui}header,main{max-width:1600px;margin:auto;padding:24px}a{color:#e1c66f}h1{font-size:30px}h2{margin-top:45px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(310px,1fr));gap:16px}figure{margin:0;background:#202924;border:1px solid #47544c}img{width:100%;height:290px;object-fit:contain;background:#080b09}figcaption{padding:13px}code{display:block;font-size:12px;overflow-wrap:anywhere}button{margin:8px;padding:10px;color:#eee;background:#334038;border:1px solid #9bad96}video{width:100%;max-height:800px}p{max-width:1000px}.charts img{height:auto;max-width:900px}</style><header><h1>Gullyverse — authoritative current evidence</h1><p>HEAD e3dbbc233f1f12f5e4d96333db3b797e75da4760 / codex/navigation-board. Production contents preserved. Actual website captures, not concept art. Portrait is touch emulation on SwiftShader. Click a frame to inspect the original resolution PNG.</p><p><a href="../../docs/gullyverse-current-final-review.md">Final review (Markdown)</a> · <a href="../../docs/gullyverse-current-visual-baseline.md">Current baseline (Markdown)</a> · <a href="raw/capture-metadata.json">Exact frame metadata</a> · <a href="raw/performance-summary.json">Performance</a> · <a href="raw/resource-results.json">Resource lifecycle</a> · <a href="raw/asset-inventory.json">Asset inventory</a> · <a href="PHYSICAL-DEVICE-PROCEDURE.md">Physical device procedure</a></p><p>Environmental inspection uses existing registered cameras and is labeled individually. Public controls provide live entry/map/playback/boundary evidence. Camera can move during screenshot acquisition; JSON records start/end poses. CSS-size captures preserve viewport PNG size but do not imply a DPR1 framebuffer.</p></header><main><button onclick="filter('all')">All current frames</button><button onclick="filter('desktop')">Desktop</button><button onclick="filter('mobile')">Portrait / touch</button><div class="grid" id="current">'''+''.join(cards)+'''</div><h2>Recorded visitor journey and trace</h2>'''+''.join(recordings)+'''<p><a href="traces/visitor.zip">Full Playwright trace</a> · <a href="raw/navigation-trace-summary.json">Navigation trace summary</a> · <a href="raw/visitor.json">Public journey and perimeter results</a> · <a href="raw/navigation-followup.json">Unrecorded route follow-up</a></p><h2>Measured lifecycle and frame intervals</h2><div class="charts"><a href="resource-lifecycle.svg"><img src="resource-lifecycle.png"></a><a href="frame-intervals.svg"><img src="frame-intervals.png"></a></div><h2>Previously matched tunnel-exit correction (historical)</h2><p>These historical before/after frames establish the correction already present at review start. Today's stage rear uses its registered review pose; different pose/DPR comparisons are qualitative, not pixel identity claims.</p><div class="grid">'''+''.join(comparisons)+'''</div><h2>Original references and earlier implementation</h2><p>Current user-approved appearance overrides these older images. The old extra signs/lighting/layout are not mandatory restoration targets.</p><div class="grid">'''+''.join(references)+'''</div></main><script>function filter(g){document.querySelectorAll('#current figure').forEach(e=>e.style.display=g==='all'||e.dataset.group===g?'':'none')}</script></html>'''
(r/'gallery.html').write_text(page)
(r/'raw/gallery-summary.json').write_text(json.dumps({'currentScreenshotCount':len(cards),'captureMetadataCount':len(metadata['captures']),'historicalComparisonCount':len(comparisons),'referencesCount':len(references),'recordingCount':len(recordings)},indent=2))
